  // ── Falling Words game ─────────────────────────────────────────
  "Press Enter to begin the Hangul City defense mission.": { "zh-Hans": "按 Enter 开始韩文城市防御任务。", "zh-Hant": "按 Enter 開始韓文城市防禦任務。", es: "Pulsa Enter para iniciar la misión de defensa.", "pt-BR": "Pressione Enter para iniciar a missão de defesa.", id: "Tekan Enter untuk memulai misi pertahanan.", th: "กด Enter เพื่อเริ่มภารกิจป้องกันเมือง", vi: "Nhấn Enter để bắt đầu nhiệm vụ phòng thủ.", fil: "Pindutin ang Enter para simulan ang misyon.", ms: "Tekan Enter untuk mula misi pertahanan.", fr: "Appuyez sur Entrée pour lancer la mission.", de: "Enter drücken, um die Verteidigungsmission zu starten.", ru: "Нажмите Enter, чтобы начать миссию обороны.", tr: "Savunma görevini başlatmak için Enter'a bas." },
  "Shield charging! Complete a word and press Enter to blast it.": { "zh-Hans": "护盾充能中！拼完单词按 Enter 击破。", "zh-Hant": "護盾充能中！拼完單字按 Enter 擊破。", es: "¡Escudo cargando! Completa una palabra y pulsa Enter.", "pt-BR": "Escudo carregando! Complete uma palavra e pressione Enter.", id: "Perisai mengisi! Selesaikan kata lalu tekan Enter.", th: "กำลังชาร์จโล่! พิมพ์คำให้ครบแล้วกด Enter", vi: "Đang nạp khiên! Hoàn thành từ và nhấn Enter.", fil: "Nagcha-charge ang shield! Buuin ang salita at Enter.", ms: "Perisai mengecas! Lengkapkan perkataan dan tekan Enter.", fr: "Bouclier en charge ! Complétez un mot et appuyez sur Entrée.", de: "Schild lädt! Wort vervollständigen und Enter drücken.", ru: "Щит заряжается! Завершите слово и нажмите Enter.", tr: "Kalkan doluyor! Kelimeyi tamamla ve Enter'a bas." },
  "The city shield collapsed. Press Enter to redeploy instantly.": { "zh-Hans": "城市护盾崩溃。按 Enter 立即再出击。", "zh-Hant": "城市護盾崩潰。按 Enter 立即再出擊。", es: "El escudo cayó. Pulsa Enter para volver al combate.", "pt-BR": "O escudo caiu. Pressione Enter para voltar ao combate.", id: "Perisai kota runtuh. Tekan Enter untuk terjun lagi.", th: "โล่เมืองพังแล้ว กด Enter เพื่อกลับเข้าสู่สนาม", vi: "Khiên thành phố sụp đổ. Nhấn Enter để triển khai lại.", fil: "Bumagsak ang shield. Pindutin ang Enter para bumalik.", ms: "Perisai kota runtuh. Tekan Enter untuk kembali.", fr: "Bouclier détruit. Appuyez sur Entrée pour repartir.", de: "Stadtschild zerstört. Enter für sofortigen Neustart.", ru: "Щит города разрушен. Нажмите Enter для возврата.", tr: "Şehir kalkanı çöktü. Enter ile hemen geri dön." },
  "Mission live! Type each corrupted word exactly and press Enter to blast it.": { "zh-Hans": "任务开始！准确输入被污染的单词并按 Enter 击破。", "zh-Hant": "任務開始！準確輸入被汙染的單字並按 Enter 擊破。", es: "¡Misión activa! Escribe cada palabra y pulsa Enter.", "pt-BR": "Missão ativa! Digite cada palavra e pressione Enter.", id: "Misi dimulai! Ketik tiap kata dengan tepat lalu Enter.", th: "ภารกิจเริ่ม! พิมพ์คำให้ถูกต้องแล้วกด Enter", vi: "Nhiệm vụ bắt đầu! Gõ đúng từng từ rồi nhấn Enter.", fil: "Live na ang misyon! I-type nang tama at Enter.", ms: "Misi bermula! Taip setiap perkataan dengan tepat dan Enter.", fr: "Mission lancée ! Tapez chaque mot exactement puis Entrée.", de: "Mission läuft! Jedes Wort exakt tippen und Enter drücken.", ru: "Миссия началась! Точно набирайте слова и жмите Enter.", tr: "Görev başladı! Her kelimeyi tam yaz ve Enter'a bas." },
  "Target lock failed. The word stays. Correct it with Backspace, then Enter.": { "zh-Hans": "锁定失败！单词仍在。用 Backspace 修改后按 Enter。", "zh-Hant": "鎖定失敗！單字仍在。用 Backspace 修改後按 Enter。", es: "Fallo de puntería. Corrige con Retroceso y pulsa Enter.", "pt-BR": "Falha na mira. Corrija com Backspace e pressione Enter.", id: "Gagal mengunci. Perbaiki dengan Backspace lalu Enter.", th: "ล็อกเป้าไม่สำเร็จ แก้ด้วย Backspace แล้วกด Enter", vi: "Khóa mục tiêu thất bại. Sửa bằng Backspace rồi Enter.", fil: "Palya ang target lock. Itama gamit ang Backspace, Enter.", ms: "Kunci sasaran gagal. Betulkan dengan Backspace, Enter.", fr: "Verrouillage raté. Corrigez avec Retour arrière puis Entrée.", de: "Zielerfassung fehlgeschlagen. Mit Rücktaste korrigieren, Enter.", ru: "Захват цели не удался. Исправьте Backspace и нажмите Enter.", tr: "Hedef kilidi başarısız. Backspace ile düzelt, Enter'a bas." },
  "Falling word defense game for Neon Hangul City": { "zh-Hans": "守护霓虹韩文城市的落词防御游戏", "zh-Hant": "守護霓虹韓文城市的落字防禦遊戲", es: "Juego de defensa con palabras que caen", "pt-BR": "Jogo de defesa com palavras que caem", id: "Gim pertahanan kata jatuh", th: "เกมป้องกันเมืองด้วยคำที่ร่วงลงมา", vi: "Trò chơi phòng thủ với chữ rơi", fil: "Falling word defense game", ms: "Permainan pertahanan kata jatuh", fr: "Jeu de défense avec mots qui tombent", de: "Wortabwehr-Spiel für Neon Hangul City", ru: "Игра защиты с падающими словами", tr: "Düşen kelime savunma oyunu" },
  "CITY DEFENSE": { "zh-Hans": "城市防御任务", "zh-Hant": "城市防禦任務", es: "DEFENSA DE LA CIUDAD", "pt-BR": "DEFESA DA CIDADE", id: "PERTAHANAN KOTA", th: "ภารกิจป้องกันเมือง", vi: "PHÒNG THỦ THÀNH PHỐ", fil: "DEPENSA NG LUNGSOD", ms: "PERTAHANAN KOTA", fr: "DÉFENSE DE LA VILLE", de: "STADTVERTEIDIGUNG", ru: "ОБОРОНА ГОРОДА", tr: "ŞEHİR SAVUNMASI" },
  "DECODE CORRUPTED WORDS": { "zh-Hans": "解码污染单词", "zh-Hant": "解碼汙染單字", es: "DESCIFRA LAS PALABRAS", "pt-BR": "DECIFRE AS PALAVRAS", id: "PECAHKAN KATA RUSAK", th: "ถอดรหัสคำที่ปนเปื้อน", vi: "GIẢI MÃ TỪ BỊ NHIỄM", fil: "I-DECODE ANG MGA SALITA", ms: "NYAHKOD PERKATAAN ROSAK", fr: "DÉCODEZ LES MOTS", de: "WÖRTER ENTSCHLÜSSELN", ru: "РАСШИФРУЙ СЛОВА", tr: "BOZUK KELİMELERİ ÇÖZ" },
