  "Starting a conversation": { "zh-Hans": "开启对话", "zh-Hant": "開啟對話", es: "Iniciar una conversación", "pt-BR": "Iniciar uma conversa", id: "Memulai obrolan", th: "เริ่มบทสนทนา", vi: "Bắt chuyện", fil: "Pagsisimula ng usapan", ms: "Memulakan perbualan", fr: "Engager la conversation", de: "Ein Gespräch beginnen", ru: "Начало разговора", tr: "Sohbete başlama" },
