  "Sharing a local tip": { "zh-Hans": "分享本地小贴士", "zh-Hant": "分享在地小撇步", es: "Compartir un consejo local", "pt-BR": "Compartilhar uma dica local", id: "Berbagi tip lokal", th: "แนะนำข้อมูลท้องถิ่น", vi: "Chia sẻ mẹo địa phương", fil: "Pagbabahagi ng local tip", ms: "Berkongsi tip tempatan", fr: "Partager un bon plan local", de: "Lokalen Tipp teilen", ru: "Местный совет", tr: "Yerel ipucu paylaşma" },

