  "Next line": { "zh-Hans": "下一句歌词", "zh-Hant": "下一句歌詞", es: "Siguiente línea", "pt-BR": "Próxima linha", id: "Baris berikutnya", th: "บรรทัดถัดไป", vi: "Dòng tiếp theo", fil: "Susunod na linya", ms: "Baris seterusnya", fr: "Ligne suivante", de: "Nächste Zeile", ru: "Следующая строка", tr: "Sonraki satır" },
  "Type the scene. Feel the emotion.": { "zh-Hans": "输入这段场景，感受其中情绪。", "zh-Hant": "輸入這段場景，感受其中情緒。", es: "Escribe la escena. Siente la emoción.", "pt-BR": "Digite a cena. Sinta a emoção.", id: "Ketik adegannya. Rasakan emosinya.", th: "พิมพ์ฉากนี้ แล้วสัมผัสอารมณ์", vi: "Gõ cảnh phim. Cảm nhận cảm xúc.", fil: "I-type ang eksena. Damhin ang emosyon.", ms: "Taip adegan. Rasai emosinya.", fr: "Tapez la scène. Ressentez l'émotion.", de: "Szene tippen. Emotion spüren.", ru: "Наберите сцену. Прочувствуйте эмоцию.", tr: "Sahneyi yaz. Duyguyu hisset." },
  "Korean dialogue": { "zh-Hans": "韩语台词", "zh-Hant": "韓語台詞", es: "Diálogo coreano", "pt-BR": "Diálogo coreano", id: "Dialog Korea", th: "บทพูดภาษาเกาหลี", vi: "Lời thoại tiếng Hàn", fil: "Korean na diyalogo", ms: "Dialog Korea", fr: "Dialogue coréen", de: "Koreanischer Dialog", ru: "Корейский диалог", tr: "Korece diyalog" },
  "Next scene": { "zh-Hans": "下一场景", "zh-Hant": "下一場景", es: "Siguiente escena", "pt-BR": "Próxima cena", id: "Adegan berikutnya", th: "ฉากถัดไป", vi: "Cảnh tiếp theo", fil: "Susunod na eksena", ms: "Adegan seterusnya", fr: "Scène suivante", de: "Nächste Szene", ru: "Следующая сцена", tr: "Sonraki sahne" },
  "A COURSE THAT GROWS WITH YOU": { "zh-Hans": "与你一同成长的课程", "zh-Hant": "與你一同成長的課程", es: "UN CURSO QUE CRECE CONTIGO", "pt-BR": "UM CURSO QUE CRESCE COM VOCÊ", id: "KURSUS YANG TUMBUH BERSAMAMU", th: "คอร์สที่เติบโตไปกับคุณ", vi: "KHÓA HỌC LỚN LÊN CÙNG BẠN", fil: "KURSONG LUMALAGO KASAMA KA", ms: "KURSUS YANG BERKEMBANG BERSAMA ANDA", fr: "UN PARCOURS QUI ÉVOLUE AVEC VOUS", de: "EIN KURS, DER MIT DIR WÄCHST", ru: "КУРС, КОТОРЫЙ РАСТЁТ С ВАМИ", tr: "SENİNLE BÜYÜYEN BİR KURS" },
  "No Korean keyboard required": { "zh-Hans": "无需韩文键盘", "zh-Hant": "無需韓文鍵盤", es: "No necesitas teclado coreano", "pt-BR": "Não precisa de teclado coreano", id: "Tak perlu keyboard Korea", th: "ไม่ต้องมีคีย์บอร์ดเกาหลี", vi: "Không cần bàn phím tiếng Hàn", fil: "Hindi kailangan ng Korean keyboard", ms: "Tiada papan kekunci Korea diperlukan", fr: "Pas besoin de clavier coréen", de: "Keine koreanische Tastatur nötig", ru: "Корейская клавиатура не нужна", tr: "Korece klavye gerekmez" },
  "Works on mobile and desktop": { "zh-Hans": "支持手机与电脑", "zh-Hant": "支援手機與電腦", es: "Funciona en móvil y escritorio", "pt-BR": "Funciona no celular e no computador", id: "Berfungsi di ponsel dan desktop", th: "ใช้ได้ทั้งมือถือและคอมพิวเตอร์", vi: "Dùng được trên di động và máy tính", fil: "Gumagana sa mobile at desktop", ms: "Berfungsi pada mudah alih dan desktop", fr: "Fonctionne sur mobile et ordinateur", de: "Funktioniert auf Handy und Desktop", ru: "Работает на телефоне и компьютере", tr: "Mobil ve masaüstünde çalışır" },
  "Free core course": { "zh-Hans": "核心课程免费", "zh-Hant": "核心課程免費", es: "Curso principal gratis", "pt-BR": "Curso principal gratuito", id: "Kursus inti gratis", th: "คอร์สหลักฟรี", vi: "Khóa học chính miễn phí", fil: "Libreng core course", ms: "Kursus teras percuma", fr: "Cours principal gratuit", de: "Kernkurs kostenlos", ru: "Основной курс бесплатно", tr: "Temel kurs ücretsiz" },
  "Free learning promise": { "zh-Hans": "免费学习承诺", "zh-Hant": "免費學習承諾", es: "Promesa de aprendizaje gratuito", "pt-BR": "Promessa de aprendizado gratuito", id: "Janji belajar gratis", th: "คำมั่นเรียนฟรี", vi: "Cam kết học miễn phí", fil: "Pangako ng libreng pagkatuto", ms: "Janji pembelajaran percuma", fr: "Promesse d'apprentissage gratuit", de: "Versprechen: kostenloses Lernen", ru: "Обещание бесплатного обучения", tr: "Ücretsiz öğrenme sözü" },
  "LEARN FIRST": { "zh-Hans": "学习优先", "zh-Hant": "學習優先", es: "PRIMERO APRENDER", "pt-BR": "APRENDER PRIMEIRO", id: "BELAJAR DULU", th: "เรียนก่อน", vi: "HỌC TRƯỚC", fil: "MATUTO MUNA", ms: "BELAJAR DAHULU", fr: "APPRENDRE D'ABORD", de: "ZUERST LERNEN", ru: "СНАЧАЛА УЧЁБА", tr: "ÖNCE ÖĞREN" },
  "Free practice, without interruptions.": { "zh-Hans": "不打断心流的免费练习。", "zh-Hant": "不打斷心流的免費練習。", es: "Práctica gratuita, sin interrupciones.", "pt-BR": "Prática gratuita, sem interrupções.", id: "Latihan gratis, tanpa gangguan.", th: "ฝึกฟรี ไม่มีสิ่งรบกวน", vi: "Luyện tập miễn phí, không gián đoạn.", fil: "Libreng praktis, walang abala.", ms: "Latihan percuma, tanpa gangguan.", fr: "Pratique gratuite, sans interruption.", de: "Kostenlos üben, ohne Unterbrechung.", ru: "Бесплатная практика без прерываний.", tr: "Kesintisiz, ücretsiz alıştırma." },
  "Core lessons and games stay free. If ads are introduced, they appear only between activities—not beside the typing field or during a game.": { "zh-Hans": "核心课程与游戏保持免费。若引入广告，也只会出现在活动之间，不会在输入框旁或游戏中。", "zh-Hant": "核心課程與遊戲保持免費。若引入廣告，也只會出現在活動之間，不會在輸入框旁或遊戲中。", es: "Las lecciones y juegos siguen gratis. Si hay anuncios, solo entre actividades.", "pt-BR": "Lições e jogos seguem gratuitos. Se houver anúncios, só entre atividades.", id: "Pelajaran & gim tetap gratis. Jika ada iklan, hanya di antara aktivitas.", th: "บทเรียนและเกมยังฟรี หากมีโฆษณา จะแสดงเฉพาะระหว่างกิจกรรมเท่านั้น", vi: "Bài học và trò chơi vẫn miễn phí. Nếu có quảng cáo, chỉ giữa các hoạt động.", fil: "Libre pa rin ang aralin at laro. Kung may ads, sa pagitan lang ng aktibidad.", ms: "Pelajaran & permainan kekal percuma. Jika ada iklan, hanya antara aktiviti.", fr: "Leçons et jeux restent gratuits. Les pubs n'apparaîtraient qu'entre activités.", de: "Lektionen und Spiele bleiben kostenlos. Werbung nur zwischen Aktivitäten.", ru: "Уроки и игры остаются бесплатными. Реклама — только между активностями.", tr: "Dersler ve oyunlar ücretsiz kalır. Reklam olursa yalnızca aktiviteler arasında." },
  "Type Korean. Play your way.": { "zh-Hans": "打韩文，像玩游戏一样学。", "zh-Hant": "打韓文，像玩遊戲一樣學。", es: "Escribe coreano. Juega a tu manera.", "pt-BR": "Digite coreano. Jogue do seu jeito.", id: "Ketik Korea. Main sesukamu.", th: "พิมพ์เกาหลี เล่นในแบบของคุณ", vi: "Gõ tiếng Hàn. Chơi theo cách bạn.", fil: "Mag-type ng Korean. Laruin sa paraan mo.", ms: "Taip Korea. Main cara anda.", fr: "Tapez le coréen. Jouez à votre façon.", de: "Koreanisch tippen. Spiel deinen Weg.", ru: "Печатай по-корейски. Играй по-своему.", tr: "Korece yaz. Kendi tarzınla oyna." },
